  const dates = JSON.parse(r.dates_json || '{}');
  const dateEntry = dates['2024-07-15'];
  if (dateEntry && dateEntry.status === 'available') {
    console.log(JSON.stringify({
      flight_number: r.flight_id,
      origin: r.origin,
      destination: r.destination,
      departure_time_est: r.departure_time,
      arrival_time_est: r.arrival_time,
      status: dateEntry.status,
      available_seats: dateEntry.available_seats,
      prices: dateEntry.prices
    }, null, 2));
  }
});
