cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');
const rows = db.prepare(\"SELECT flight_id, dates_json FROM flights WHERE source_skill='tau2Airline' AND origin='SFO' AND destination='JFK'\").all();
if (rows.length === 0) {
  console.log('No SFO->JFK flights found at all');
  // Check what routes exist
  const allRoutes = db.prepare(\"SELECT DISTINCT origin, destination FROM flights WHERE source_skill='tau2Airline'\").all();
  console.log('Available routes:', JSON.stringify(allRoutes));
} else {
  rows.forEach(r => {
    const dates = JSON.parse(r.dates_json || '{}');
    console.log(r.flight_id, 'dates:', Object.keys(dates).join(', '));
  });
}
"

